// === Tab: mySketch ===
// just figuring out inline shaders

// the fragment shader is from the Book of Shaders
// https://thebookofshaders.com/13/
// Author @patriciogv - 2015
// http://patriciogonzalezvivo.com

let sh, gl;
let vert, frag;

function preload(){
    vert = `
			// simplest vert file
			attribute vec3 aPosition;

			void main() {
				vec4 pos = vec4(aPosition, 1.0);
				pos.xy = pos.xy * 2.0 - 1.0;

				// send the vertex information on to the fragment shader
				gl_Position = pos;
			}
    `;

    frag = `
			#ifdef GL_ES
			precision mediump float;
			#endif

			uniform vec2 u_resolution;
			uniform vec2 u_mouse;
			uniform float u_time;

			float random (in vec2 _st) {
					return fract(sin(dot(_st.xy,vec2(12.9898,78.233)))*43758.5453123);
			}

			// Based on Morgan McGuire @morgan3d
			// https://www.shadertoy.com/view/4dS3Wd
			float noise (in vec2 _st) {
					vec2 i = floor(_st);
					vec2 f = fract(_st);

					// Four corners in 2D of a tile
					float a = random(i);
					float b = random(i + vec2(1.0, 0.0));
					float c = random(i + vec2(0.0, 1.0));
					float d = random(i + vec2(1.0, 1.0));

					vec2 u = f * f * (3.0 - 2.0 * f);

					return mix(a, b, u.x) + (c - a) * u.y * (1.0 - u.x) + (d - b) * u.x * u.y;
			}

			#define NUM_OCTAVES 7

			float fbm ( in vec2 _st) {
					float v = 0.0;
					float a = 0.5;
					vec2 shift = vec2(10.0);
					// Rotate to reduce axial bias
					mat2 rot = mat2( cos(0.5), sin(0.5),
													-sin(0.5), cos(0.5));
					for (int i = 0; i < NUM_OCTAVES; ++i) {
							v += a * noise(_st);
							_st = rot * _st * 2.0 + shift;
							a *= 0.5;
					}
					return v;
			}

			void main() {
					vec2 st = gl_FragCoord.xy / u_resolution.xy * 3.;
					vec3 color = vec3(0.0);

					vec2 q = vec2(0.);
					q.x = fbm(st + 0.00 * u_time);
					q.y = fbm(st + vec2(1.0));

					vec2 r = vec2(0.);
					r.x = fbm(st + 1.0 * q + vec2(1.7,9.2) + 0.150 * u_time );
					r.y = fbm(st + 1.0 * q + vec2(8.3,2.8) + 0.126 * u_time);

					float f = fbm(st + r);

					color = mix(vec3(0.101961,0.619608,0.666667),
											vec3(0.666667,0.666667,0.498039),
											clamp((f*f)*4.0,0.0,1.0));

					color = mix(color,
											vec3(0,0,0.164706),
											clamp(length(q),0.0,1.0));

					color = mix(color,
											vec3(0.666667,1.,1.),
											clamp(length(r.x),0.0,1.0));

					gl_FragColor = vec4((f*f*f + .6 * f*f + .5 * f) * color,1.0);
			}
    `;
 }

function setup() {
  // got shader? use WEBGL mode
  createCanvas(1112, 834, WEBGL);
  noStroke();

	gl = this.canvas.getContext('webgl');
	gl.disable(gl.DEPTH_TEST);//*/

  sh = createShader(vert,frag);
}

function draw() {
  // shader() sets the active shader with our shader
  shader(sh);

  sh.setUniform("u_resolution", [width, height]);
  sh.setUniform("u_time", millis() / 1000.0);
  sh.setUniform("u_mouse", [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, height, 0)]);

  // something for the shader to draw on
  rect(0,0,width, height);
}

function windowResized(){ resizeCanvas(width, height); }

// save jpg
let lapse = 0;    // mouse timer
function mousePressed(){
  if (millis() - lapse > 400){
    save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
    lapse = millis();
  } 
}

